#!/usr/bin/env node
// MIT. Redis source inspection, prepared customers and the original seller.
import { mkdir, open, readFile, rm } from 'node:fs/promises';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { describeRedisFile, openRedisSourceFile } from './config.mjs';
import { prepareRedisSeller, verifyPreparedRedisSeller } from './prepare.mjs';
import { startRedisSeller, createRedisNativeFactory } from './merchant.mjs';

const HELP = `Redis / Valkey merchant (Node 22.16+)
  init       --directory NEW_DIRECTORY [--transport redis|upstash-rest]
             [--topology standalone|cluster|sentinel]
  describe   --source source.json
  inspect    --source source.json
  preflight  --source source.json
  query      --source source.json --query NAME --input input.json [--output NEW_FILE]
  prepare    --source source.json --plan merchant-plan.json --directory NEW_DIRECTORY
  verify     --directory PREPARED_DIRECTORY
  start      --directory PREPARED_DIRECTORY [--port 8423] [--operations-port 8424]
             [--facilitator HTTPS_URL] [--allow-local-facilitator] [--no-operations]
             [--max-in-flight 64] [--drain-grace-ms 60000] [--availability-dir DIRECTORY]
  run        Alias for start.
  serve      --source source.json --config service.json [same launch options]
  workspace  setup|create|open|inspect|save|preview|prepare|stage|resume [workspace options]
Credentials come from passwordEnv, sentinelPasswordEnv or tokenEnv. init/describe/inspect/prepare/verify are offline.
Seller documentation and operations use the original developer portal and local operator interface.`;

async function readInput(filename) {
  const handle = await open(resolve(filename), 'r');
  try {
    const before = await handle.stat();
    if (!before.isFile() || before.size > 1048576) throw new TypeError('REDIS_INPUT_FILE_INVALID');
    const bytes = Buffer.alloc(before.size + 1); let total = 0;
    while (total < bytes.length) {
      const { bytesRead } = await handle.read(bytes, total, bytes.length - total, null);
      if (!bytesRead) break;
      total += bytesRead;
    }
    const after = await handle.stat();
    if (total !== before.size || after.size !== before.size || after.mtimeMs !== before.mtimeMs)
      throw new TypeError('REDIS_INPUT_FILE_CHANGED');
    return JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes.subarray(0, total)));
  } finally { await handle.close(); }
}
async function writeNew(filename, bytes) {
  const file = await open(resolve(filename), 'wx', 0o600);
  try { await file.writeFile(bytes); await file.sync(); } finally { await file.close(); }
}
const encode = value => JSON.stringify(value, null, 2) + '\n';
const print = value => process.stdout.write(JSON.stringify(value) + '\n');

export async function initRedisWorkspace(directory, { transport = 'redis', topology = 'standalone' } = {}) {
  if (!['redis', 'upstash-rest'].includes(transport)) throw new TypeError('REDIS_TRANSPORT_INVALID');
  if (!['standalone', 'cluster', 'sentinel'].includes(topology)) throw new TypeError('REDIS_TOPOLOGY_INVALID');
  if (transport === 'upstash-rest' && topology !== 'standalone') throw new TypeError('REDIS_TRANSPORT_TOPOLOGY_CONFLICT');
  const template = transport === 'upstash-rest' ? 'example-upstash-source.json' :
    topology === 'standalone' ? 'example-source.json' : 'example-' + topology + '-source.json';
  const target = resolve(directory); await mkdir(target, { mode: 0o700 });
  try {
    for (const [input, output] of [[template, 'source.json'], ['example-merchant-plan.json', 'merchant-plan.json']])
      await writeNew(resolve(target, output), await readFile(new URL('./' + input, import.meta.url)));
    await writeNew(resolve(target, 'input.json'), encode({}));
    if (process.platform !== 'win32') {
      const dir = await open(target, 'r'); try { await dir.sync(); } finally { await dir.close(); }
    }
    return { directory: target, source: resolve(target, 'source.json'), plan: resolve(target, 'merchant-plan.json'),
      input: resolve(target, 'input.json') };
  } catch (issue) { await rm(target, { recursive: true, force: true }); throw issue; }
}

export async function main(args = process.argv.slice(2)) {
  if (args[0] === 'workspace') return (await import('./workspace/cli.mjs')).main(args.slice(1));
  if (!args.length || args.includes('--help')) { process.stdout.write(HELP + '\n'); return; }
  const command = args[0], options = new Map();
  const switches = ['--allow-local-facilitator', '--no-operations'];
  const launch = ['--port', '--operations-port', '--facilitator', '--allow-local-facilitator', '--no-operations',
    '--max-in-flight', '--drain-grace-ms', '--availability-dir'];
  for (let index = 1; index < args.length; index++) {
    const flag = args[index];
    if (options.has(flag)) throw new TypeError('REDIS_DUPLICATE_OPTION');
    if (switches.includes(flag)) { options.set(flag, true); continue; }
    if (!['--directory', '--transport', '--topology', '--source', '--config', '--plan', '--query', '--input', '--output', ...launch].includes(flag) ||
        !args[index + 1] || args[index + 1].startsWith('--')) throw new TypeError(HELP);
    options.set(flag, args[++index]);
  }
  const allowed = { init: ['--directory', '--transport', '--topology'], describe: ['--source'], inspect: ['--source'], preflight: ['--source'],
    query: ['--source', '--query', '--input', '--output'], prepare: ['--source', '--plan', '--directory'], verify: ['--directory'],
    start: ['--directory', ...launch], run: ['--directory', ...launch], serve: ['--source', '--config', ...launch] };
  if (!Object.hasOwn(allowed, command)) throw new TypeError(HELP);
  if ([...options.keys()].some(flag => !allowed[command].includes(flag))) throw new TypeError('REDIS_OPTION_NOT_VALID_FOR_COMMAND');
  const required = (...keys) => {
    for (const key of keys) if (!options.has(key)) throw new TypeError('Missing ' + key);
  };
  const integer = (flag, fallback) => {
    const value = options.get(flag) ?? String(fallback);
    if (!/^\d+$/.test(value) || !Number.isSafeInteger(Number(value))) throw new TypeError('REDIS_INTEGER_OPTION_INVALID:' + flag);
    return Number(value);
  };
  const sourceFile = options.has('--source') ? resolve(options.get('--source')) : undefined;
  let result;
  if (command === 'init') {
    required('--directory'); result = await initRedisWorkspace(options.get('--directory'), { transport: options.get('--transport'), topology: options.get('--topology') });
  } else if (command === 'describe' || command === 'inspect') {
    required('--source'); result = await describeRedisFile(sourceFile);
  } else if (command === 'prepare') {
    required('--source', '--plan', '--directory');
    result = await prepareRedisSeller({ sourceFile, planFile: options.get('--plan'), directory: options.get('--directory') });
  } else if (command === 'verify') {
    required('--directory'); result = await verifyPreparedRedisSeller(options.get('--directory'));
  } else if (command === 'preflight' || command === 'query') {
    required('--source'); if (command === 'query') required('--query', '--input');
    const input = command === 'query' ? await readInput(options.get('--input')) : undefined;
    const { source } = await openRedisSourceFile(sourceFile);
    try {
      result = command === 'query' ? await source.query(options.get('--query'), input) :
        { source: await source.inspect(), status: await source.status() };
    } finally { await source.close(); }
    if (options.has('--output')) {
      await writeNew(options.get('--output'), encode(result));
      result = { output: resolve(options.get('--output')), rowCount: result.rowCount,
        truncated: result.truncated, ...(result.nextInput ? { nextInput: result.nextInput } : {}) };
    }
  } else {
    let database = sourceFile, configFile = options.get('--config');
    if (command === 'start' || command === 'run') {
      required('--directory'); const prepared = await verifyPreparedRedisSeller(options.get('--directory'));
      database = resolve(prepared.directory, 'source.json'); configFile = resolve(prepared.directory, 'service.json');
    } else required('--source', '--config');
    if (options.has('--no-operations') && options.has('--operations-port') ||
        options.has('--allow-local-facilitator') && !options.has('--facilitator'))
      throw new TypeError('REDIS_LAUNCH_OPTIONS_CONFLICT');
    const port = integer('--port', 8423), operationsPort = options.has('--no-operations') ? null : integer('--operations-port', 8424);
    const maxInFlight = integer('--max-in-flight', 64), drainGraceMs = integer('--drain-grace-ms', 60000);
    if (port > 65535 || operationsPort > 65535 || maxInFlight < 1 || maxInFlight > 1024 || drainGraceMs < 1000 || drainGraceMs > 300000)
      throw new RangeError('REDIS_LAUNCH_LIMIT_INVALID');
    const nativeFactory = await createRedisNativeFactory({ facilitator: options.get('--facilitator'),
      allowLocalFacilitator: options.has('--allow-local-facilitator') });
    const session = await startRedisSeller({ sourceFile: database, configFile, port, operationsPort,
      maxInFlight, drainGraceMs, nativeFactory,
      ...(options.has('--availability-dir') ? { availabilityDirectory: resolve(options.get('--availability-dir')) } : {}) });
    const stop = () => { void session.close().then(() => { process.exitCode = 0; }, () => { process.exitCode = 1; }); };
    for (const signal of ['SIGINT', 'SIGTERM']) process.once(signal, stop);
    const originalClose = session.close.bind(session);
    session.close = async () => {
      try { return await originalClose(); }
      finally { for (const signal of ['SIGINT', 'SIGTERM']) process.removeListener(signal, stop); }
    };
    print({ url: session.url, mode: session.mode, docs: session.url + '/_seller/docs',
      openapi: session.url + '/_seller/openapi.json', dataSource: 'Redis / Valkey named read products',
      ...(session.operations ? { operations: session.operations.url, availability: session.operations.availabilityUrl,
        availabilityControl: session.operations.availabilityControlUrl } : {}) });
    return session;
  }
  print(result); return result;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main().catch(issue => {
  process.stderr.write(JSON.stringify({ error: issue.code ?? issue.message ?? 'REDIS_OPERATION_FAILED',
    ...(issue.query ? { query: issue.query } : {}) }) + '\n'); process.exitCode = 1;
});

// MIT. Fixed native read products share the original seller scalar contract.
import { record, compileParameterSchema, bindParameters, QueryInputError } from '../sqlite/parameters.mjs';
export { QueryInputError };
const NAME = /^[A-Za-z_][A-Za-z0-9_]{0,63}$/;
const text = value => typeof value === 'string' && value.isWellFormed() && value.length > 0 && Buffer.byteLength(value) <= 1024 && !/[\x00-\x1f\x7f]/.test(value);
const own = (value, key) => Object.hasOwn(value, key);
const limit = (value, min, max, name) => {
  if (!Number.isInteger(value) || value < min || value > max) throw new TypeError('REDIS_LIMIT_INVALID:' + name);
  return value;
};

export function compileRedisQueries(input) {
  if (!record(input) || !Object.keys(input).length || Object.keys(input).length > 64)
    throw new TypeError('REDIS_NAMED_QUERIES_REQUIRED');
  const result = Object.create(null);
  for (const [name, raw] of Object.entries(input)) {
    if (!NAME.test(name) || !record(raw) || !['get', 'hash', 'sorted-set', 'stream', 'list', 'set'].includes(raw.kind) ||
        Object.keys(raw).some(key => !['kind', 'key', 'parameters', 'fields', 'columns', 'offset', 'after',
          'cursor', 'scanCount', 'maxRows', 'maxBytes', 'timeoutMs'].includes(key))) throw new TypeError('REDIS_QUERY_INVALID');
    const parameters = compileParameterSchema(raw.parameters, name), used = new Set();
    for (const spec of Object.values(parameters)) if (!['string', 'integer'].includes(spec.type) || spec.nullable)
      throw new TypeError('REDIS_NON_NULL_TEXT_OR_INTEGER_REQUIRED');
    let key;
    if (text(raw.key)) key = raw.key;
    else {
      if (!record(raw.key) || Object.keys(raw.key).some(k => !['prefix', 'parameter'].includes(k)) ||
          !text(raw.key.prefix) || !NAME.test(raw.key.parameter)) throw new TypeError('REDIS_KEY_INVALID');
      const spec = parameters[raw.key.parameter];
      if (!spec || spec.type !== 'string' || !Array.isArray(spec.enum) ||
          spec.enum.some(value => !text(value) || !text(raw.key.prefix + value)))
        throw new TypeError('REDIS_KEY_REQUIRES_DECLARED_ENUM');
      used.add(raw.key.parameter); key = { prefix: raw.key.prefix, parameter: raw.key.parameter };
    }
    const fieldMap = Object.create(null);
    if (['hash', 'stream'].includes(raw.kind)) {
      if (!record(raw.fields) || !Object.keys(raw.fields).length || Object.keys(raw.fields).length > 63)
        throw new TypeError('REDIS_PROJECTED_FIELDS_REQUIRED');
      for (const [column, field] of Object.entries(raw.fields)) {
        if (!NAME.test(column) || raw.kind === 'stream' && column === 'id' || !text(field))
          throw new TypeError('REDIS_PROJECTED_FIELD_INVALID');
        fieldMap[column] = field;
      }
      if (own(raw, 'columns')) throw new TypeError('REDIS_COLUMNS_COME_FROM_FIELDS');
    } else if (own(raw, 'fields')) throw new TypeError('REDIS_FIELDS_NOT_SUPPORTED');
    const defaults = { get: ['value'], 'sorted-set': ['member', 'score'], list: ['index', 'value'], set: ['member'] };
    const columns = defaults[raw.kind] ? raw.columns ?? defaults[raw.kind]
      : [...(raw.kind === 'stream' ? ['id'] : []), ...Object.keys(fieldMap)];
    const columnCount = defaults[raw.kind]?.length ?? Object.keys(fieldMap).length + (raw.kind === 'stream' ? 1 : 0);
    if (!Array.isArray(columns) || columns.some(column => !NAME.test(column)) ||
        new Set(columns).size !== columns.length || columns.length !== columnCount)
      throw new TypeError('REDIS_COLUMNS_INVALID');
    if (own(raw, 'offset')) {
      const spec = parameters[raw.offset];
      if (!['sorted-set', 'list'].includes(raw.kind) || !spec || spec.type !== 'integer' ||
          !own(spec, 'minimum') || BigInt(spec.minimum) < 0n ||
          !own(spec, 'maximum') || BigInt(spec.maximum) > 10000000n)
        throw new TypeError('REDIS_OFFSET_REQUIRES_BOUNDED_INTEGER');
      used.add(raw.offset);
    }
    if (own(raw, 'after')) {
      const spec = parameters[raw.after];
      if (raw.kind !== 'stream' || !spec || spec.type !== 'string' || (spec.maxLength ?? 4096) > 41)
        throw new TypeError('REDIS_AFTER_REQUIRES_STREAM_ID_TEXT');
      used.add(raw.after);
    }
    if (raw.kind === 'set') {
      const spec = parameters[raw.cursor];
      if (!NAME.test(raw.cursor) || !spec || spec.type !== 'string' ||
          (spec.maxLength ?? 4096) > 20 || used.has(raw.cursor))
        throw new TypeError('REDIS_CURSOR_REQUIRES_UINT64_TEXT');
      used.add(raw.cursor);
      if (own(spec, 'default')) redisScanCursor(spec.default, raw.cursor);
      for (const value of spec.enum ?? []) redisScanCursor(value, raw.cursor);
    } else if (own(raw, 'cursor') || own(raw, 'scanCount')) throw new TypeError('REDIS_SCAN_REQUIRES_SET');
    if (Object.keys(parameters).some(field => !used.has(field))) throw new TypeError('REDIS_UNUSED_PARAMETER');
    const maxRows = limit(raw.maxRows ?? (['get', 'hash'].includes(raw.kind) ? 1 : raw.kind === 'set' ? 1000 : 100), 1, 1000, 'maxRows');
    if (['get', 'hash'].includes(raw.kind) && maxRows !== 1) throw new TypeError('REDIS_LOOKUP_RETURNS_ONE_ROW');
    result[name] = { kind: raw.kind, key, fields: fieldMap, columns: [...columns], parameters,
      parameterOrder: Object.keys(parameters), ...(raw.offset ? { offset: raw.offset } : {}),
      ...(raw.after ? { after: raw.after } : {}),
      ...(raw.kind === 'set' ? { cursor: raw.cursor, scanCount: limit(raw.scanCount ?? Math.min(100, maxRows), 1, maxRows, 'scanCount') } : {}), maxRows,
      maxBytes: limit(raw.maxBytes ?? 524288, 1024, 917504, 'maxBytes'),
      timeoutMs: limit(raw.timeoutMs ?? 1500, 50, 30000, 'timeoutMs') };
    // Defaults and enum values already passed the shared scalar compiler.
    if (raw.after) {
      if (own(parameters[raw.after], 'default')) streamId(parameters[raw.after].default, raw.after);
      for (const value of parameters[raw.after].enum ?? []) streamId(value, raw.after);
    }
  }
  return result;
}

export function redisScanCursor(value, field) {
  if (typeof value !== 'string' || !/^(0|[1-9]\d{0,19})$/.test(value) || BigInt(value) > 18446744073709551615n)
    throw new QueryInputError(field, 'EXPECTED_SCAN_CURSOR');
  return value;
}

function streamId(value, field) {
  if (value === '-') return value;
  const match = /^(0|[1-9]\d{0,19})-(0|[1-9]\d{0,19})$/.exec(value);
  if (!match || BigInt(match[1]) > 18446744073709551615n || BigInt(match[2]) > 18446744073709551615n)
    throw new QueryInputError(field, 'EXPECTED_STREAM_ID');
  return value;
}

export function bindRedisParameters(query, input) {
  const named = bindParameters(query, input);
  return query.parameterOrder.map(name => {
    const value = named['$' + name];
    if (typeof value === 'string' && !value.isWellFormed()) throw new QueryInputError(name, 'TEXT_NOT_WELL_FORMED');
    if (typeof value === 'string' && value.includes('\0')) throw new QueryInputError(name, 'TEXT_CONTAINS_NUL');
    if (query.after === name) streamId(value, name);
    if (query.cursor === name) redisScanCursor(value, name);
    return typeof value === 'bigint' ? String(value) : value;
  });
}

export function bindRedisQuery(query, input) {
  const values = bindRedisParameters(query, input);
  const named = Object.fromEntries(query.parameterOrder.map((name, index) => [name, values[index]]));
  return { key: typeof query.key === 'string' ? query.key : query.key.prefix + named[query.key.parameter],
    position: ['sorted-set', 'list'].includes(query.kind) ? String(named[query.offset] ?? '0')
      : query.kind === 'set' ? named[query.cursor] ?? '0' : named[query.after] ?? '-', values: named };
}

export function describeRedisQueries(queries) {
  return Object.fromEntries(Object.entries(queries).map(([name, query]) => [name, {
    kind: query.kind, parameters: structuredClone(query.parameters), parameterOrder: [...query.parameterOrder],
    columns: [...query.columns], maxRows: query.maxRows, maxBytes: query.maxBytes, timeoutMs: query.timeoutMs,
    ...(query.offset ? { offset: query.offset } : {}), ...(query.after ? { after: query.after } : {}),
    ...(query.cursor ? { cursor: query.cursor, scanCount: query.scanCount } : {}),
  }]));
}

{
  "schema": "stellar-forge.redis-merchant-plan.v1",
  "publicOrigin": "https://redis-merchant.example",
  "payment": {
    "scheme": "exact",
    "network": "stellar:testnet",
    "asset": "UNVERIFIED_DEMO_ASSET",
    "payTo": "UNVERIFIED_DEMO_RECIPIENT",
    "amount": "10000",
    "maxTimeoutSeconds": 60
  },
  "routes": [
    {
      "id": "list_feed",
      "path": "/list",
      "method": "GET",
      "query": "list_feed",
      "serviceName": "Ordered list feed",
      "description": "One current page of the declared Redis list with exact zero-based indexes and original values. Use nextInput to continue; live changes can move list indexes.",
      "tags": [
        "redis",
        "list"
      ],
      "example": {
        "offset": "0"
      },
      "parameterDescriptions": {
        "offset": "Zero-based list index within the declared bounds. Continue using the previous result's nextInput."
      }
    },
    {
      "id": "member_catalog",
