    assert.equal(run.result.checks.length,6);assert.ok(run.result.checks.every(check=>check.passed));
    assert.ok(run.result.checks.find(check=>check.query==='list_feed').pages.length>=3);
    assert.equal(run.result.checks.find(check=>check.query==='member_catalog').pages.at(-1).scanCursor,'0');
    assert.equal(run.result.release.releaseId??run.result.release.id,'commissioned-customer');
    assert.deepEqual(await call('/api/commissioning/receive',{requestId:run.id,contractId:contract.id},[202]),run);
    let cursor='',seen=[],observedComplete=false,retainedPages=0;
    do{
      const value=await call('/api/commissioning/rows?run='+run.id+'&check=member_catalog&limit=50&cursor='+encodeURIComponent(cursor));
      seen.push(...value.rows);retainedPages+=value.pages.length;observedComplete=value.complete;cursor=value.nextCursor;
      assert.equal(value.sourceIncomplete,null);
    }while(cursor);
    assert.equal(observedComplete,true);
    assert.equal(new Set(seen.map(row=>JSON.stringify(row.member))).size,132);
    if(page){
      await page.locator('#commission-make-handover').click();
      await page.locator('#status').filter({hasText:'Complete customer handover is ready.'}).waitFor({timeout:120000});
      handover=JSON.parse(await page.locator('#commission-handover-json').innerText());
      // The browser shows the public result; retrieve the original request via history.
      const history=await call('/api/commissioning/history');
      const saved=history.items.find(item=>item.kind==='commission-handover'&&item.runId===run.id);
      assert.ok(saved);handover=await call('/api/commissioning/operation?id='+saved.id);
      const downloadEvent=page.waitForEvent('download');await page.locator('#commission-download-handover').click();
      const download=await downloadEvent,path=join(workspace.root,'commissioning-customer-handover.zip');
      await download.saveAs(path);const bytes=await readFile(path);
      assert.equal(sha(bytes),handover.result.file.sha256);browserDownload={path,bytes:bytes.length,sha256:sha(bytes)};
      assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);
    }else handover=await finish(await call('/api/commissioning/handover',{requestId:prefix+'customer-handover',runId:run.id},[202]));
    assert.equal(handover.status,'COMPLETED',JSON.stringify(handover));
    assert.equal(handover.result.status,'HANDOVER_READY');assertZip((await workspace.commissioningFile(handover.id)).bytes,handover.result.members);
    const response=await fetch(server.url+'/api/commissioning/handover?id='+handover.id,{headers:{'x-workspace-token':server.token}});
    const zip=Buffer.from(await response.arrayBuffer());
    assert.equal(response.status,200);assert.equal(response.headers.get('x-content-sha256'),handover.result.file.sha256);
    assert.equal(sha(zip),handover.result.file.sha256);
    const first=await call('/api/commissioning/history?limit=2');
    const second=await call('/api/commissioning/history?limit=2&after='+first.nextCursor);
    assert.equal(first.items.length,2);assert.ok(first.nextCursor);assert.notEqual(second.items[0].id,first.items[0].id);
    assert.deepEqual(browserIssues,[]);
    const head=await workspace.restore({requestId:prefix+'restore-reviewed-head',expectedHead:workspace.metadata().head,
      revisionId:contract.input.revisionId,note:'Retain the commissioned customer source as current'});
    assert.equal(head.status,'COMPLETED',JSON.stringify(head));
    return {result:'PASS',workspaceId:original.workspace.id,contractId:contract.id,runId:run.id,handoverId:handover.id,
      revisionId:contract.input.revisionId,sourceLimit:{runId:limitedRun.id,requestId:limitedRows.sourceIncomplete.requestId,
        reason:limitedRows.sourceIncomplete.continuationUnavailable,retainedRows:limitedRows.rows.length},
      products:run.result.checks.map(check=>({id:check.id,rows:check.rowCount,pages:check.pages.length})),
      set:{uniqueMembers:132,retainedPages},file:handover.result.file,members:handover.result.members.length,
      ...(browserDownload?{browserDownload}:{})};
  }finally{page?.off('pageerror',onPageError);}
}
export async function verifyRedisCommissioningReopen(workspace,received){
  assert.equal(workspace.metadata().id,received.workspaceId);
  const run=workspace.operation(received.runId),handover=workspace.operation(received.handoverId);
  assert.equal(run.status,'COMPLETED');assert.equal(run.result.status,'RECEIVED');assert.equal(run.attempts,1);
  assert.deepEqual(workspace.commissioningReceive({requestId:run.id,contractId:received.contractId}),run);
  assert.deepEqual(await workspace.commissioningHandover({requestId:handover.id,runId:run.id}),handover);
  const file=await workspace.commissioningFile(handover.id);
  assert.equal(sha(file.bytes),received.file.sha256);assert.equal(file.bytes.length,received.file.bytes);
  assertZip(file.bytes,handover.result.members);
  return {result:'PASS',sameWorkspace:true,originalReceivingAttempts:run.attempts,originalHandoverAttempts:handover.attempts,
    bytes:file.bytes.length,sha256:sha(file.bytes)};
}

#!/usr/bin/env node
// MIT. Operate the same saved commissioning contracts from the original workspace CLI.
import { open } from 'node:fs/promises';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { openRedisAuthoringWorkspace } from './model.mjs';

const HELP=[
  'Redis customer commissioning in an existing workspace',
  '  template --directory WORKSPACE [--revision SHA256]',
  '  review --directory WORKSPACE --input WORKBOOK_JSON',
  '  save --directory WORKSPACE --input WORKBOOK_JSON --request ID --review-digest SHA256',
  '  receive --directory WORKSPACE --contract SAVED_REQUEST --request ID',
  '  continue --directory WORKSPACE --id ORIGINAL_REQUEST',
  '  history --directory WORKSPACE [--after REQUEST] [--limit 20]',
  '  inspect --directory WORKSPACE --id REQUEST',
  '  rows --directory WORKSPACE --run REQUEST --check EXAMPLE [--cursor PAGE:ROW] [--limit 50]',
  '  handover --directory WORKSPACE --run REQUEST --request ID',
  '  export --directory WORKSPACE --id HANDOVER_REQUEST --output NEW_ZIP',
  '',
  'Close the existing browser workspace process before acquiring its original writer from this CLI.',
  'A browser operator can use Customer commissioning from the original workspace URL.',
].join('\n');
async function inputFile(path){
  const file=await open(resolve(path),'r');
  try{
    const before=await file.stat();
    if(!before.isFile()||before.size>5242880)throw new TypeError('Use a complete commissioning input or workbook within 5 MiB.');
    const bytes=Buffer.alloc(before.size+1);let size=0;
    while(size<bytes.length){const read=await file.read(bytes,size,bytes.length-size,null);if(!read.bytesRead)break;size+=read.bytesRead;}
    const after=await file.stat();
    if(size!==before.size||after.size!==before.size||after.mtimeMs!==before.mtimeMs)throw new Error('The commissioning input changed while reading.');
    return JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes.subarray(0,size)));
  }finally{await file.close();}
}
export async function redisCommissioningOperatorCli(args=process.argv.slice(2)){
  if(!args.length||args.length===1&&['help','--help'].includes(args[0])){process.stdout.write(HELP+'\n');return;}
  const [command,...rest]=args,options=new Map(),allowed={
    template:['directory','revision'],review:['directory','input'],save:['directory','input','request','review-digest'],
    receive:['directory','contract','request'],continue:['directory','id'],history:['directory','after','limit'],
    inspect:['directory','id'],rows:['directory','run','check','cursor','limit'],handover:['directory','run','request'],
    export:['directory','id','output'],
  };
  if(!Object.hasOwn(allowed,command))throw new TypeError(HELP);
  for(let index=0;index<rest.length;index+=2){
    const name=rest[index]?.slice(2),value=rest[index+1];
    if(!rest[index]?.startsWith('--')||!allowed[command].includes(name)||options.has(name)||!value||value.startsWith('--'))
      throw new TypeError('Use each supported flag and value once.\n'+HELP);
    options.set(name,value);
  }
  const required=name=>{const value=options.get(name);if(!value)throw new TypeError('Missing --'+name+'.');return value;};
  const workspace=await openRedisAuthoringWorkspace(required('directory'));let result;
  try{
    if(command==='template'){
      const selected=await workspace.commissioningTemplate({revisionId:options.get('revision')});
      result={schema:'stellar-forge.redis-commissioning-workbook.v1',...selected,note:''};
    }else if(command==='review'||command==='save'){
      const supplied=await inputFile(required('input'));
      const input=supplied.schema==='stellar-forge.redis-commissioning-input.v1'
        ?{revisionId:workspace.metadata().head,input:supplied,customerPlan:null}
        :supplied.schema==='stellar-forge.redis-commissioning-workbook.v1'
          ?{revisionId:supplied.revisionId,input:supplied.input,customerPlan:supplied.customerPlan??null}:null;
      if(!input)throw new TypeError('Choose an original commissioning input or workbook.');
      result=command==='review'?await workspace.commissioningReview(input):
        await workspace.commissioningSave({...input,requestId:required('request'),digest:required('review-digest'),note:supplied.note??''});
    }else if(command==='receive'||command==='handover'){
      const id=required('request');
      if(command==='receive')workspace.commissioningReceive({requestId:id,contractId:required('contract')});
      else await workspace.commissioningHandover({requestId:id,runId:required('run')});
      await workspace.queue;result=workspace.operation(id);
    }else if(command==='continue'){
      const id=required('id'),record=workspace.operation(id);
      if(record.kind==='commission-contract')await workspace.resume(id);
      else workspace.commissioningContinue(id);
      await workspace.queue;result=workspace.operation(id);
    }else if(command==='history')result=await workspace.commissioningHistory({after:options.get('after')??'',limit:Number(options.get('limit')??20)});
    else if(command==='inspect'){
      result=workspace.operation(required('id'));
      if(!result.kind.startsWith('commission-'))throw new TypeError('Choose an original commissioning operation.');
    }else if(command==='rows')result=await workspace.commissioningRows({runId:required('run'),checkId:required('check'),cursor:options.get('cursor')??'',limit:Number(options.get('limit')??50)});
    else if(command==='export'){
      const file=await workspace.commissioningFile(required('id')),path=resolve(required('output')),output=await open(path,'wx',0o600);
      try{await output.writeFile(file.bytes);await output.sync();}finally{await output.close();}
      result={path,name:file.name,bytes:file.bytes.length,sha256:file.sha256};
    }
    process.stdout.write(JSON.stringify(result,null,2)+'\n');
    if(result?.status==='FAILED')process.exitCode=1;
    if(result?.result?.status==='ACCEPTANCE_MISMATCH')process.exitCode=2;
    return result;
  }finally{await workspace.close();}
}
if(process.argv[1]&&resolve(process.argv[1])===fileURLToPath(import.meta.url))
  redisCommissioningOperatorCli().catch(error=>{process.stderr.write(JSON.stringify({error:error.code??'REDIS_COMMISSIONING_FAILED',message:error.message})+'\n');process.exitCode=1;});

// MIT. Customer commissioning contracts and handovers in the original workspace.
import { readFile, open, lstat, unlink } from 'node:fs/promises';
import { join } from 'node:path';
import { createHash } from 'node:crypto';
import { normalizeRedisCommissioning, redisCommissioningRequestId } from './commission.mjs';
import { redisWorkspaceBinding } from './model.mjs';
import { REDIS_CERTIFICATE_FILES } from '../connection-profile.mjs';
import { compileRedisQueries, bindRedisQuery } from '../declaration.mjs';
import { compileRedisMerchantPlan } from '../prepare.mjs';
import { validateCustomerExportPlan } from './customer-export.mjs';
import { createScientificArchive } from '../../wqx-water-quality/jobs/archive.mjs';

export const COMMISSION_CONTRACT_KIND='commission-contract';
export const COMMISSION_RECEIVE_KIND='commission-receive';
export const COMMISSION_HANDOVER_KIND='commission-handover';
const KINDS=[COMMISSION_CONTRACT_KIND,COMMISSION_RECEIVE_KIND,COMMISSION_HANDOVER_KIND];
const MAX_ATOMIC=170141183460469231731687303715884105727n;
const plain=v=>v!==null&&typeof v==='object'&&!Array.isArray(v);
const ordered=v=>Array.isArray(v)?v.map(ordered):plain(v)
  ?Object.fromEntries(Object.keys(v).sort().map(k=>[k,ordered(v[k])])):v;
const stable=v=>JSON.stringify(ordered(v));
const sha=v=>createHash('sha256').update(v).digest('hex');
const encode=v=>Buffer.from(JSON.stringify(v,null,2)+'\n');
const issue=(code,message,status=422)=>Object.assign(new Error(message),{code,status});
export function commissioningFields(value,allowed) {
  if(!plain(value)||Object.keys(value).some(name=>!allowed.includes(name)))
    throw issue('REDIS_COMMISSIONING_FIELDS_INVALID','Use the supported commissioning fields.');
}
function identifier(value){
  if(typeof value!=='string'||!/^[A-Za-z0-9][A-Za-z0-9_-]{0,79}$/.test(value))
    throw issue('REDIS_COMMISSIONING_ID_INVALID','Select the original saved request ID.');
  return value;
}
function digest(value){
  if(typeof value!=='string'||!/^[a-f0-9]{64}$/.test(value))
    throw issue('REDIS_COMMISSIONING_DIGEST_INVALID','Select the reviewed complete input digest.');
  return value;
}
function blob(workspace,key){
  const row=workspace.db.prepare('SELECT bytes FROM blobs WHERE sha=?').get(digest(key));
  if(!row||sha(row.bytes)!==key)
    throw issue('REDIS_COMMISSIONING_BLOB_CHANGED','An original retained file is missing or changed.');
  return Buffer.from(row.bytes);
}
function sourceSetup(workspace,revisionId){
  const meta=workspace.metadata(),revision=workspace.revision(revisionId??meta.head),certificates={};
  for(const item of REDIS_CERTIFICATE_FILES)
    if(meta[item.fingerprint])certificates[item.profile]=new TextDecoder('utf-8',{fatal:true}).decode(blob(workspace,meta[item.fingerprint]));
  return {label:meta.label,source:structuredClone(revision.source),plan:structuredClone(revision.plan),certificates};
}
function defaultCustomerPlan(input) {
  const compiled=compileRedisMerchantPlan(input.setup.source.queries,input.setup.plan);
  let aggregate=0n;
  const products=input.setup.plan.routes.map(route=>{
    const spec=input.setup.source.queries[route.query],offer=compiled.service.routes.find(item=>item.id===route.id).offer;
    const selected=offer.accepts[0],amount=String(selected.amount);
    aggregate+=BigInt(amount);
    return {id:route.id,query:route.query,kind:spec.kind,
      ...(spec.kind==='set'?{cursorParameter:spec.cursor}:{}),
      input:Object.fromEntries(Object.entries(route.example??{}).map(([key,value])=>[key,String(value)])),
      maxAtomic:amount,acceptIndex:0,paymentFlow:'authorization'};
  });
  return {schema:'tjlabs.redis-customer-export.v1',operationId:input.operationId+'-customer',
    budget:{maxCalls:Math.max(products.length,1),maxAtomic:String(aggregate>MAX_ATOMIC?MAX_ATOMIC:aggregate)},
    response:{maxBytes:1048576,timeoutMs:30000},products};
}
export function commissioningTemplate(workspace,{revisionId}={}) {
  const setup=sourceSetup(workspace,revisionId),selected=workspace.revision(revisionId??workspace.metadata().head);
  const input={schema:'stellar-forge.redis-commissioning-input.v1',
    operationId:'customer-'+selected.id.slice(0,16),requestId:'customer-create-'+selected.id.slice(0,16),setup,
    checks:setup.plan.routes.map((route,index)=>({id:'example-'+(index+1),query:route.query,input:structuredClone(route.example??{}),
      allPages:false,maxPages:100,maxRows:10000,expected:{rowCount:1}}))};
  return {revisionId:selected.id,input,customerPlan:defaultCustomerPlan(input)};
}
function customerReview(selected,customerPlan){
  if(customerPlan===null||customerPlan===undefined)return null;
  if(encode(customerPlan).length>1048576)throw issue('REDIS_COMMISSIONING_CUSTOMER_PLAN_TOO_LARGE','Keep the complete customer export plan within 1 MiB.');
  const plan=validateCustomerExportPlan(customerPlan),compiled=compileRedisMerchantPlan(selected.setup.source.queries,selected.setup.plan);
  const queries=compileRedisQueries(selected.setup.source.queries),terms=[];
  for(const product of plan.products){
    const route=selected.setup.plan.routes.find(row=>row.id===product.id),native=route&&selected.setup.source.queries[route.query];
    const operation=compiled.service.routes.find(row=>row.id===product.id),offer=operation?.offer.accepts[product.acceptIndex];
    if(!route||!native||(route.method??'GET')!=='GET'||(product.query??product.id)!==route.query||product.kind!==native.kind||
        native.kind==='set'&&(product.cursorParameter??'cursor')!==native.cursor||!offer)
      throw issue('REDIS_COMMISSIONING_CUSTOMER_BINDING_CHANGED','Select the saved GET operation, source query, read kind and offer.');
    bindRedisQuery(queries[route.query],product.input);
    if(BigInt(offer.amount)>BigInt(product.maxAtomic))
      throw issue('REDIS_COMMISSIONING_CUSTOMER_BUDGET_INVALID','The selected product price exceeds its per-call ceiling.');
    terms.push({id:product.id,query:route.query,kind:native.kind,path:route.path,
      network:offer.network,asset:offer.asset,payTo:offer.payTo,advertisedAtomic:String(offer.amount),
      maxAtomic:product.maxAtomic,acceptIndex:product.acceptIndex,paymentFlow:product.paymentFlow});
